<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\StoreBlockedTimeRequest; use App\Models\BlockedTime; use App\Services\ProviderScheduleService; use Carbon\CarbonImmutable; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class ProviderBlockedTimeController extends Controller { public function index(Request $request): JsonResponse {$p=$this->provider($request);return response()->json(['data'=>$p->blockedTimes()->orderBy('starts_at')->get()]);} public function store(StoreBlockedTimeRequest $request,ProviderScheduleService $service): JsonResponse {$p=$this->provider($request);$data=$request->validated();$data['starts_at']=CarbonImmutable::parse($data['starts_at'],$p->timezone)->utc();$data['ends_at']=CarbonImmutable::parse($data['ends_at'],$p->timezone)->utc();return response()->json(['data'=>$service->createBlockedTime($p,$data)],201);} public function destroy(Request $request,BlockedTime $blockedTime,ProviderScheduleService $service): JsonResponse {$p=$this->provider($request);abort_unless($blockedTime->provider_id===$p->id,403);$service->deleteBlockedTime($blockedTime);return response()->json(['message'=>'Blocked time deleted.']);} private function provider(Request $request){return $request->user()->provider ?: abort(403,'Provider profile required.');} }
